      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'ਸਪਲਾਇਰ ਦਾ ਬਿੱਲ ਜਿਵੇਂ ਛਪਿਆ ਹੈ ਉਵੇਂ ਭਰੋ — ਹਰ ਲਾਈਨ ਸਟਾਕ ਵਿੱਚ ਜੁੜਦੀ ਹੈ (ਕੱਚਾ / ਪੈਕਿੰਗ ਮਾਲ → ਸਟੋਰ ਲੇਜਰ, ਤਿਆਰ ਮਾਲ → ਇਨਵੈਂਟਰੀ) ਅਤੇ ਬਿੱਲ ਨੰਬਰ ਹਵਾਲੇ ਵਜੋਂ ਦਰਜ ਹੁੰਦਾ ਹੈ।',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'ਆਮਦ: ਹਰ ਸਪਲਾਇਰ ਬਿੱਲ ਇੱਥੇ ਦਰਜ ਕਰੋ — ਕੱਚਾ ਮਾਲ, ਪੈਕਿੰਗ ਮਾਲ ਜਾਂ ਤਿਆਰ ਮਾਲ। ਸਟਾਕ ਆਪਣੇ ਆਪ ਵਧਦਾ ਹੈ ਅਤੇ ਬਿੱਲ ਨੰਬਰ ਆਈਟਮ ਦੇ ਇਤਿਹਾਸ ਵਿੱਚ ਦਿਖਦਾ ਹੈ।',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'ਹਾਲੇ ਕੋਈ ਖਰੀਦ ਬਿੱਲ ਨਹੀਂ — ਜਦੋਂ ਮਾਲ ਸਪਲਾਇਰ ਦੇ ਬਿੱਲ ਨਾਲ ਆਵੇ ਤਾਂ "ਸਪਲਾਇਰ ਬਿੱਲ ਦਰਜ ਕਰੋ" ਦਬਾਓ।',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'ਹਾਲੇ ਕੋਈ ਹਲਚਲ ਨਹੀਂ — ਬਿੱਲ ਨੰਬਰ ਨਾਲ ਸਟਾਕ ਲੈਣ ਲਈ ਸਪਲਾਇਰ ਬਿੱਲ ਦਰਜ ਕਰੋ।',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'ਖਰੀਦ / ਡਿਸਪੈਚ / ਪ੍ਰੋਡਕਸ਼ਨ ਦੀ ਲਾਈਨ ਦਬਾ ਕੇ ਖੋਲ੍ਹੋ। "ਸ਼ੁਰੂਆਤੀ / ਸੋਧ" ਉਹ ਸਟਾਕ ਹੈ ਜੋ ਇਤਿਹਾਸ ਰੱਖਣ ਤੋਂ ਪਹਿਲਾਂ ਹੱਥੀਂ ਸੈੱਟ ਕੀਤਾ ਗਿਆ ਸੀ।',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'ਇਸ ਬਿੱਲ ਨਾਲ ਜੋੜੀ ਮਾਤਰਾ ਸਟਾਕ ਵਿੱਚੋਂ ਵਾਪਸ ਘਟਾ ਦਿੱਤੀ ਜਾਵੇਗੀ ਅਤੇ ਲੇਜਰ ਐਂਟਰੀਆਂ ਹਟ ਜਾਣਗੀਆਂ। ਐਂਟਰੀ ਰਜਿਸਟਰ ਵਿੱਚ CANCELLED ਵਜੋਂ ਰਹੇਗੀ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ।',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'ਐਂਟਰੀ ਰਜਿਸਟਰ ਵਿੱਚ CANCELLED ਵਜੋਂ ਰਹੇਗੀ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ।',
      'wrong supplier / duplicate entry / goods returned': 'ਗਲਤ ਸਪਲਾਇਰ / ਦੁਹਰੀ ਐਂਟਰੀ / ਮਾਲ ਵਾਪਸ',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'ਸੁਝਾਅ: "ਸਪਲਾਇਰ ਬਿੱਲ ਦਰਜ ਕਰੋ" ਪੂਰਾ ਬਿੱਲ GST ਸਮੇਤ ਦਰਜ ਕਰਦਾ ਹੈ ਅਤੇ ਸਾਰੀਆਂ ਆਈਟਮਾਂ ਦਾ ਸਟਾਕ ਇੱਕੋ ਵਾਰ ਜੋੜਦਾ ਹੈ।',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'ਗਾਹਕ ਜਿਨ੍ਹਾਂ ਨੂੰ ਵੇਚਦੇ ਹੋ ਅਤੇ ਸਪਲਾਇਰ ਜਿਨ੍ਹਾਂ ਤੋਂ ਖਰੀਦਦੇ ਹੋ — GSTIN, ਪਤਾ, ਉਧਾਰ ਦਿਨ',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'ਹਾਲੇ ਕੋਈ ਪਾਰਟੀ ਨਹੀਂ — ਆਪਣੇ ਗਾਹਕ ਅਤੇ ਸਪਲਾਇਰ ਇੱਥੇ ਜੋੜੋ (ਇੱਕ-ਵਾਰੀ ਨਾਮ ਬਿੱਲ ਉੱਤੇ ਵੀ ਲਿਖਿਆ ਜਾ ਸਕਦਾ ਹੈ)।',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'ਮਿਆਦ ਦੀ ਆਮਦ ਸਪਲਾਈ — ਸਪਲਾਇਰ ਬਿੱਲ-ਵਾਰ, HSN / ਰੇਟ-ਵਾਰ ਦਿੱਤਾ ਟੈਕਸ (ਇਨਪੁੱਟ ਟੈਕਸ ਕ੍ਰੈਡਿਟ)। B2B = GSTIN ਵਾਲਾ ਸਪਲਾਇਰ, URD = ਗੈਰ-ਰਜਿਸਟਰਡ। ਰੱਦ ਐਂਟਰੀਆਂ ਦਿਖਦੀਆਂ ਹਨ ਪਰ ਜੋੜ ਵਿੱਚ ਨਹੀਂ।',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'ਹਾਈਲਾਈਟ ਕੀਤੀ ਲਾਈਨ ਦਾ ਮਤਲਬ: \'ਤੱਕ\' ਤਾਰੀਖ ਦਾ ਅੰਤਿਮ ਬਕਾਇਆ ਅੱਜ ਦੇ ਸਟਾਕ ਤੋਂ ਵੱਖ ਹੈ — \'ਤੱਕ\' ਤਾਰੀਖ ਤੋਂ ਬਾਅਦ ਦੀਆਂ ਮੂਵਮੈਂਟਾਂ, ਜਾਂ ਐਪ ਤੋਂ ਬਾਹਰ ਕੀਤੀ ਤਬਦੀਲੀ।',
      'Adjustment (approved)': 'ਐਡਜਸਟਮੈਂਟ (ਮਨਜ਼ੂਰ)',
      'Adjustment no': 'ਐਡਜਸਟਮੈਂਟ ਨੰ',
      'All items': 'ਸਾਰੀਆਂ ਆਈਟਮਾਂ',
      'All types': 'ਸਾਰੀਆਂ ਕਿਸਮਾਂ',
      'Balance synced': 'ਬਕਾਇਆ ਸਿੰਕ ਕੀਤਾ',
      'Bill / dispatch / invoice no, party, note…': 'ਬਿੱਲ / ਡਿਸਪੈਚ / ਇਨਵੌਇਸ ਨੰ, ਪਾਰਟੀ, ਨੋਟ…',
      'Changed outside the app': 'ਐਪ ਤੋਂ ਬਾਹਰ ਬਦਲਿਆ',
      'Clear dates': 'ਤਾਰੀਖਾਂ ਹਟਾਓ',
      'Closing (period)': 'ਅੰਤਿਮ (ਮਿਆਦ)',
      'Dispatch no': 'ਡਿਸਪੈਚ ਨੰ',
      'Dispatch voided (returned)': 'ਡਿਸਪੈਚ ਰੱਦ (ਵਾਪਸ)',
      'Doc / Bill no': 'ਡੌਕ / ਬਿੱਲ ਨੰ',
      'Documents': 'ਦਸਤਾਵੇਜ਼',
      'Every stock change is recorded automatically with its document number — supplier bill, dispatch no., invoice no., batch code, adjustment code. Tap a row to open the document. "Opening stock" is the balance carried from before the ledger started.': 'ਹਰ ਸਟਾਕ ਤਬਦੀਲੀ ਆਪਣੇ ਦਸਤਾਵੇਜ਼ ਨੰਬਰ ਨਾਲ ਆਪਣੇ-ਆਪ ਦਰਜ ਹੁੰਦੀ ਹੈ — ਸਪਲਾਇਰ ਬਿੱਲ, ਡਿਸਪੈਚ ਨੰ, ਇਨਵੌਇਸ ਨੰ, ਬੈਚ ਕੋਡ, ਐਡਜਸਟਮੈਂਟ ਕੋਡ। ਦਸਤਾਵੇਜ਼ ਖੋਲ੍ਹਣ ਲਈ ਲਾਈਨ \'ਤੇ ਟੈਪ ਕਰੋ। "ਸ਼ੁਰੂਆਤੀ ਸਟਾਕ" ਲੈਜਰ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਬਕਾਇਆ ਹੈ।',
      'Every stock change of every product and material, with its document number and the balance after the movement — like an SAP material document list (MB51). Tap the item to open its full ledger; tap the document number to open the bill / dispatch / batch.': 'ਹਰ ਪ੍ਰੋਡਕਟ ਤੇ ਸਮੱਗਰੀ ਦੀ ਹਰ ਸਟਾਕ ਤਬਦੀਲੀ, ਦਸਤਾਵੇਜ਼ ਨੰਬਰ ਤੇ ਮੂਵਮੈਂਟ ਤੋਂ ਬਾਅਦ ਦੇ ਬਕਾਏ ਨਾਲ — SAP ਮਟੀਰੀਅਲ ਡੌਕੂਮੈਂਟ ਲਿਸਟ (MB51) ਵਾਂਗ। ਪੂਰਾ ਲੈਜਰ ਖੋਲ੍ਹਣ ਲਈ ਆਈਟਮ \'ਤੇ ਟੈਪ ਕਰੋ; ਬਿੱਲ / ਡਿਸਪੈਚ / ਬੈਚ ਖੋਲ੍ਹਣ ਲਈ ਦਸਤਾਵੇਜ਼ ਨੰਬਰ \'ਤੇ।',
      'Export CSV': 'CSV ਐਕਸਪੋਰਟ',
      'Exported (CSV) — open in Excel or share.': 'ਐਕਸਪੋਰਟ ਹੋ ਗਿਆ (CSV) — Excel ਵਿੱਚ ਖੋਲ੍ਹੋ ਜਾਂ ਸਾਂਝਾ ਕਰੋ।',
      'Find a bill / dispatch / invoice / batch no': 'ਬਿੱਲ / ਡਿਸਪੈਚ / ਇਨਵੌਇਸ / ਬੈਚ ਨੰ ਲੱਭੋ',
      'Finished products': 'ਤਿਆਰ ਪ੍ਰੋਡਕਟ',
      'From (party / depot)': 'ਕਿੱਥੋਂ (ਪਾਰਟੀ / ਡਿਪੂ)',
      'GRN / challan / ref no': 'GRN / ਚਲਾਨ / ਰੈਫ ਨੰ',
      'Goods received against a supplier invoice? Use Billing → Purchases (Inward) instead — it records the bill number, GST and payable too.': 'ਸਪਲਾਇਰ ਇਨਵੌਇਸ ਦੇ ਬਦਲੇ ਮਾਲ ਆਇਆ? ਇਸ ਦੀ ਬਜਾਏ ਬਿਲਿੰਗ → ਖਰੀਦ (ਇਨਵਰਡ) ਵਰਤੋ — ਉਹ ਬਿੱਲ ਨੰਬਰ, GST ਤੇ ਦੇਣਦਾਰੀ ਵੀ ਦਰਜ ਕਰਦਾ ਹੈ।',
      'In': 'ਇਨ',
      'In (period)': 'ਇਨ (ਮਿਆਦ)',
      'Invoice cancelled (restored)': 'ਇਨਵੌਇਸ ਰੱਦ (ਸਟਾਕ ਵਾਪਸ)',
      'Invoice no': 'ਇਨਵੌਇਸ ਨੰ',
      'Issue / consumed': 'ਜਾਰੀ / ਖਪਤ',
      'Item deleted': 'ਆਈਟਮ ਮਿਟਾਈ',
      'Item lines': 'ਆਈਟਮ ਲਾਈਨਾਂ',
      'Item name / code': 'ਆਈਟਮ ਨਾਮ / ਕੋਡ',
      'Last 7 days': 'ਪਿਛਲੇ 7 ਦਿਨ',
      'Last month': 'ਪਿਛਲਾ ਮਹੀਨਾ',
      'Last movement': 'ਆਖਰੀ ਮੂਵਮੈਂਟ',
      'Ledger exported (CSV) — open in Excel or share.': 'ਲੈਜਰ ਐਕਸਪੋਰਟ ਹੋ ਗਿਆ (CSV) — Excel ਵਿੱਚ ਖੋਲ੍ਹੋ ਜਾਂ ਸਾਂਝਾ ਕਰੋ।',
      'Materials': 'ਸਮੱਗਰੀਆਂ',
      'Moved in period only': 'ਸਿਰਫ਼ ਮਿਆਦ ਵਿੱਚ ਹਿੱਲੀਆਂ',
      'Movement': 'ਮੂਵਮੈਂਟ',
      'Movement register': 'ਮੂਵਮੈਂਟ ਰਜਿਸਟਰ',
      'Movement types': 'ਮੂਵਮੈਂਟ ਕਿਸਮਾਂ',
      'Movements': 'ਮੂਵਮੈਂਟਾਂ',
      'No documents in this period.': 'ਇਸ ਮਿਆਦ ਵਿੱਚ ਕੋਈ ਦਸਤਾਵੇਜ਼ ਨਹੀਂ।',
      'No items match.': 'ਕੋਈ ਆਈਟਮ ਮੇਲ ਨਹੀਂ ਖਾਂਦੀ।',
      'No stock movements in this period.': 'ਇਸ ਮਿਆਦ ਵਿੱਚ ਕੋਈ ਸਟਾਕ ਮੂਵਮੈਂਟ ਨਹੀਂ।',
      'One line per document number in the period — supplier bills, dispatches, invoices, production batches, adjustments — with the number of item lines and the quantity moved. Tap to open the document.': 'ਮਿਆਦ ਵਿੱਚ ਹਰ ਦਸਤਾਵੇਜ਼ ਨੰਬਰ ਦੀ ਇੱਕ ਲਾਈਨ — ਸਪਲਾਇਰ ਬਿੱਲ, ਡਿਸਪੈਚ, ਇਨਵੌਇਸ, ਪ੍ਰੋਡਕਸ਼ਨ ਬੈਚ, ਐਡਜਸਟਮੈਂਟ — ਆਈਟਮ ਲਾਈਨਾਂ ਦੀ ਗਿਣਤੀ ਤੇ ਹਿੱਲੀ ਮਾਤਰਾ ਨਾਲ। ਦਸਤਾਵੇਜ਼ ਖੋਲ੍ਹਣ ਲਈ ਟੈਪ ਕਰੋ।',
      'Opening (period)': 'ਸ਼ੁਰੂਆਤੀ (ਮਿਆਦ)',
      'Opening balance, total in, total out and closing balance of every item for the period, next to the live stock (MB5B). Opening = balance before the From date. Tap an item for its full ledger.': 'ਮਿਆਦ ਲਈ ਹਰ ਆਈਟਮ ਦਾ ਸ਼ੁਰੂਆਤੀ ਬਕਾਇਆ, ਕੁੱਲ ਇਨ, ਕੁੱਲ ਆਊਟ ਤੇ ਅੰਤਿਮ ਬਕਾਇਆ, ਲਾਈਵ ਸਟਾਕ ਦੇ ਨਾਲ (MB5B)। ਸ਼ੁਰੂਆਤੀ = \'ਤੋਂ\' ਤਾਰੀਖ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਬਕਾਇਆ। ਪੂਰੇ ਲੈਜਰ ਲਈ ਆਈਟਮ \'ਤੇ ਟੈਪ ਕਰੋ।',
      'Out': 'ਆਊਟ',
      'Out (period)': 'ਆਊਟ (ਮਿਆਦ)',
      'Period Balances': 'ਮਿਆਦ ਬਕਾਏ',
