      'Quick period': 'ਤੁਰੰਤ ਮਿਆਦ',
      'Raw & packing materials': 'ਕੱਚਾ ਤੇ ਪੈਕਿੰਗ ਮਟੀਰੀਅਲ',
      'Receipt (GRN)': 'ਰਸੀਦ (GRN)',
      'Recipe': 'ਰੈਸਿਪੀ',
      'Recipe consumption': 'ਰੈਸਿਪੀ ਖਪਤ',
      'Recorded': 'ਦਰਜ',
      'Reference': 'ਰੈਫਰੈਂਸ',
      'Reference / count sheet no (optional)': 'ਰੈਫਰੈਂਸ / ਗਿਣਤੀ ਸ਼ੀਟ ਨੰ (ਵਿਕਲਪਿਕ)',
      'Reversal': 'ਉਲਟਾਅ',
      'Stock Ledger': 'ਸਟਾਕ ਲੈਜਰ',
      'For product (optional)': 'ਕਿਸ ਪ੍ਰੋਡਕਟ ਲਈ (ਵਿਕਲਪਿਕ)',
      'Tags the consumption to a product in the stock ledger': 'ਸਟਾਕ ਲੈਜਰ ਵਿੱਚ ਖਪਤ ਨੂੰ ਇਸ ਪ੍ਰੋਡਕਟ ਨਾਲ ਜੋੜਦਾ ਹੈ',
      'Stock differs from the ledger balance by': 'ਸਟਾਕ ਲੈਜਰ ਬਕਾਏ ਤੋਂ ਇੰਨਾ ਵੱਖ ਹੈ:',
      'Stock ledger': 'ਸਟਾਕ ਲੈਜਰ',
      'Stock ledger (all in / out with doc numbers)': 'ਸਟਾਕ ਲੈਜਰ (ਸਾਰੇ ਇਨ / ਆਊਟ ਦਸਤਾਵੇਜ਼ ਨੰਬਰਾਂ ਨਾਲ)',
      'Stock now': 'ਹੁਣ ਸਟਾਕ',
      'Stock set (physical count)': 'ਸਟਾਕ ਸੈੱਟ (ਭੌਤਿਕ ਗਿਣਤੀ)',
      'The difference is posted to the stock ledger as "Stock set (physical count)" with this reference.': 'ਫ਼ਰਕ ਸਟਾਕ ਲੈਜਰ ਵਿੱਚ "ਸਟਾਕ ਸੈੱਟ (ਭੌਤਿਕ ਗਿਣਤੀ)" ਵਜੋਂ ਇਸ ਰੈਫਰੈਂਸ ਨਾਲ ਦਰਜ ਹੁੰਦਾ ਹੈ।',
      'The stock ledger is not enabled on this server yet. Ask your admin to run the stock-ledger update (tools/ff-stockledger.sh) — after that every stock movement is recorded here automatically.': 'ਇਸ ਸਰਵਰ \'ਤੇ ਸਟਾਕ ਲੈਜਰ ਅਜੇ ਚਾਲੂ ਨਹੀਂ। ਆਪਣੇ ਐਡਮਿਨ ਨੂੰ ਸਟਾਕ-ਲੈਜਰ ਅੱਪਡੇਟ (tools/ff-stockledger.sh) ਚਲਾਉਣ ਲਈ ਕਹੋ — ਉਸ ਤੋਂ ਬਾਅਦ ਹਰ ਸਟਾਕ ਮੂਵਮੈਂਟ ਇੱਥੇ ਆਪਣੇ-ਆਪ ਦਰਜ ਹੋਵੇਗੀ।',
