      'unit': 'यूनिट',
      'Add at least one item with quantity.': 'कम से कम एक आइटम मात्रा सहित जोड़ें।',
      'Every line needs a description.': 'हर लाइन के लिए विवरण चाहिए।',
      'Pick the item from the list for every line (or choose "Other / service").': 'हर लाइन के लिए सूची से आइटम चुनें (या "अन्य / सेवा" चुनें)।',
      'Check this matches the total printed on the supplier\'s bill.': 'देखें कि यह सप्लायर के बिल पर छपे कुल से मिलता है।',
      'Off — bill is recorded for payment only (use when the stock was already received manually).': 'बंद — बिल सिर्फ भुगतान के लिए दर्ज होगा (जब स्टॉक पहले ही मैनुअल प्राप्त कर लिया हो)।',
      'line(s) will be added to stock — the ledger shows the bill number as reference.': 'लाइनें स्टॉक में जुड़ेंगी — लेजर में बिल नंबर संदर्भ के रूप में दिखेगा।',
      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'सप्लायर का बिल जैसा छपा है वैसा भरें — हर लाइन स्टॉक में जुड़ती है (कच्चा / पैकिंग माल → स्टोर लेजर, तैयार माल → इन्वेंटरी) और बिल नंबर संदर्भ के रूप में दर्ज होता है।',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'आवक: हर सप्लायर बिल यहाँ दर्ज करें — कच्चा माल, पैकिंग माल या तैयार माल। स्टॉक अपने आप बढ़ता है और बिल नंबर आइटम के इतिहास में दिखता है।',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'अभी कोई खरीद बिल नहीं — जब माल सप्लायर के बिल के साथ आए तो "सप्लायर बिल दर्ज करें" दबाएँ।',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'अभी कोई मूवमेंट नहीं — बिल नंबर के साथ स्टॉक लेने के लिए सप्लायर बिल दर्ज करें।',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'खरीद / डिस्पैच / प्रोडक्शन की पंक्ति दबाकर खोलें। "ओपनिंग / समायोजन" वह स्टॉक है जो इतिहास रखने से पहले मैनुअल सेट किया गया था।',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'इस बिल से जोड़ी मात्रा स्टॉक से वापस घटा दी जाएगी और लेजर एंट्रियाँ हट जाएँगी। एंट्री रजिस्टर में CANCELLED के रूप में रहेगी। इसे वापस नहीं किया जा सकता।',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'एंट्री रजिस्टर में CANCELLED के रूप में रहेगी। इसे वापस नहीं किया जा सकता।',
      'wrong supplier / duplicate entry / goods returned': 'गलत सप्लायर / दोहरी एंट्री / माल वापस',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'सुझाव: "सप्लायर बिल दर्ज करें" पूरा बिल GST सहित दर्ज करता है और सभी आइटम का स्टॉक एक साथ जोड़ता है।',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'ग्राहक जिन्हें बेचते हैं और सप्लायर जिनसे खरीदते हैं — GSTIN, पता, उधार दिन',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'अभी कोई पार्टी नहीं — अपने ग्राहक और सप्लायर यहाँ जोड़ें (एक-बार का नाम बिल पर भी लिखा जा सकता है)।',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'अवधि की आवक सप्लाई — सप्लायर बिल-वार, HSN / रेट-वार दिया टैक्स (इनपुट टैक्स क्रेडिट)। B2B = GSTIN वाला सप्लायर, URD = अपंजीकृत। रद्द एंट्रियाँ दिखती हैं पर जोड़ में नहीं।',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'हाइलाइट की गई पंक्ति का मतलब: \'तक\' तारीख का अंतिम शेष आज के स्टॉक से अलग है — \'तक\' तारीख के बाद की मूवमेंट, या ऐप के बाहर किया गया बदलाव।',
      'Adjustment (approved)': 'समायोजन (स्वीकृत)',
