      'Documents': 'दस्तावेज़',
      'Every stock change is recorded automatically with its document number — supplier bill, dispatch no., invoice no., batch code, adjustment code. Tap a row to open the document. "Opening stock" is the balance carried from before the ledger started.': 'हर स्टॉक बदलाव अपने दस्तावेज़ नंबर के साथ अपने-आप दर्ज होता है — सप्लायर बिल, डिस्पैच नं, इनवॉइस नं, बैच कोड, समायोजन कोड। दस्तावेज़ खोलने के लिए पंक्ति पर टैप करें। "शुरुआती स्टॉक" लेजर शुरू होने से पहले का शेष है।',
      'Every stock change of every product and material, with its document number and the balance after the movement — like an SAP material document list (MB51). Tap the item to open its full ledger; tap the document number to open the bill / dispatch / batch.': 'हर प्रोडक्ट और सामग्री का हर स्टॉक बदलाव, दस्तावेज़ नंबर और मूवमेंट के बाद के शेष के साथ — SAP मटीरियल डॉक्यूमेंट लिस्ट (MB51) की तरह। पूरा लेजर खोलने के लिए आइटम पर टैप करें; बिल / डिस्पैच / बैच खोलने के लिए दस्तावेज़ नंबर पर।',
      'Export CSV': 'CSV एक्सपोर्ट',
      'Exported (CSV) — open in Excel or share.': 'एक्सपोर्ट हो गया (CSV) — Excel में खोलें या साझा करें।',
