      'Goods received against a supplier invoice? Use Billing → Purchases (Inward) instead — it records the bill number, GST and payable too.': 'सप्लायर इनवॉइस के बदले माल आया? इसके बजाय बिलिंग → खरीद (इनवर्ड) उपयोग करें — वह बिल नंबर, GST और देय राशि भी दर्ज करता है।',
