      'No stock movements in this period.': 'इस अवधि में कोई स्टॉक मूवमेंट नहीं।',
      'One line per document number in the period — supplier bills, dispatches, invoices, production batches, adjustments — with the number of item lines and the quantity moved. Tap to open the document.': 'अवधि में हर दस्तावेज़ नंबर की एक पंक्ति — सप्लायर बिल, डिस्पैच, इनवॉइस, प्रोडक्शन बैच, समायोजन — आइटम पंक्तियों की संख्या और मूव हुई मात्रा के साथ। दस्तावेज़ खोलने के लिए टैप करें।',
      'Opening (period)': 'प्रारंभिक (अवधि)',
      'Opening balance, total in, total out and closing balance of every item for the period, next to the live stock (MB5B). Opening = balance before the From date. Tap an item for its full ledger.': 'अवधि के लिए हर आइटम का प्रारंभिक शेष, कुल इन, कुल आउट और अंतिम शेष, लाइव स्टॉक के साथ (MB5B)। प्रारंभिक = \'से\' तारीख से पहले का शेष। पूरे लेजर के लिए आइटम पर टैप करें।',
