      'Tags the consumption to a product in the stock ledger': 'स्टॉक लेजर में खपत को इस प्रोडक्ट से जोड़ता है',
      'Stock differs from the ledger balance by': 'स्टॉक लेजर शेष से इतना अलग है:',
