      'Stock set (physical count)': 'स्टॉक सेट (भौतिक गिनती)',
      'The difference is posted to the stock ledger as "Stock set (physical count)" with this reference.': 'अंतर स्टॉक लेजर में "स्टॉक सेट (भौतिक गिनती)" के रूप में इस संदर्भ के साथ दर्ज होता है।',
      'The stock ledger is not enabled on this server yet. Ask your admin to run the stock-ledger update (tools/ff-stockledger.sh) — after that every stock movement is recorded here automatically.': 'इस सर्वर पर स्टॉक लेजर अभी चालू नहीं है। अपने एडमिन से स्टॉक-लेजर अपडेट (tools/ff-stockledger.sh) चलाने को कहें — उसके बाद हर स्टॉक मूवमेंट यहाँ अपने-आप दर्ज होगी।',
