      'No payments.': 'કોઈ ચુકવણી નથી.',
      'Nothing paid yet — record cheque / NEFT / cash payments here.': 'હજુ કંઈ ચૂકવ્યું નથી — ચેક / NEFT / રોકડ ચુકવણી અહીં નોંધો.',
      'Remarks (vehicle, GRN no, e-way bill…)': 'ટિપ્પણી (વાહન, GRN નં, ઈ-વે બિલ…)',
      'Freight / loading / service': 'ભાડું / લોડિંગ / સેવા',
      'unit': 'યુનિટ',
      'Add at least one item with quantity.': 'ઓછામાં ઓછી એક આઇટમ જથ્થા સાથે ઉમેરો.',
      'Every line needs a description.': 'દરેક લાઇન માટે વર્ણન જરૂરી છે.',
      'Pick the item from the list for every line (or choose "Other / service").': 'દરેક લાઇન માટે યાદીમાંથી આઇટમ પસંદ કરો (અથવા "અન્ય / સેવા" પસંદ કરો).',
      'Check this matches the total printed on the supplier\'s bill.': 'તપાસો કે આ સપ્લાયરના બિલ પર છપાયેલા કુલ સાથે મળે છે.',
      'Off — bill is recorded for payment only (use when the stock was already received manually).': 'બંધ — બિલ માત્ર ચુકવણી માટે નોંધાશે (જ્યારે સ્ટોક પહેલેથી મેન્યુઅલ મળી ગયો હોય).',
      'line(s) will be added to stock — the ledger shows the bill number as reference.': 'લાઇનો સ્ટોકમાં ઉમેરાશે — લેજરમાં બિલ નંબર સંદર્ભ તરીકે દેખાશે.',
      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'સપ્લાયરનું બિલ જેમ છપાયું છે તેમ ભરો — દરેક લાઇન સ્ટોકમાં ઉમેરાય છે (કાચો / પેકિંગ માલ → સ્ટોર લેજર, તૈયાર માલ → ઇન્વેન્ટરી) અને બિલ નંબર સંદર્ભ તરીકે નોંધાય છે.',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'આવક: દરેક સપ્લાયર બિલ અહીં દાખલ કરો — કાચો માલ, પેકિંગ માલ કે તૈયાર માલ. સ્ટોક આપોઆપ વધે છે અને બિલ નંબર આઇટમના ઇતિહાસમાં દેખાય છે.',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'હજુ કોઈ ખરીદી બિલ નથી — માલ સપ્લાયરના બિલ સાથે આવે ત્યારે "સપ્લાયર બિલ દાખલ કરો" દબાવો.',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'હજુ કોઈ હલચલ નથી — બિલ નંબર સાથે સ્ટોક લેવા સપ્લાયર બિલ દાખલ કરો.',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'ખરીદી / ડિસ્પેચ / પ્રોડક્શનની હરોળ દબાવીને ખોલો. "ઓપનિંગ / સુધારો" એ સ્ટોક છે જે ઇતિહાસ પહેલાં મેન્યુઅલ સેટ થયો હતો.',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'આ બિલથી ઉમેરેલો જથ્થો સ્ટોકમાંથી પાછો ઘટાડાશે અને લેજર એન્ટ્રીઓ દૂર થશે. એન્ટ્રી રજિસ્ટરમાં CANCELLED તરીકે રહેશે. આ પાછું નહીં થાય.',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'એન્ટ્રી રજિસ્ટરમાં CANCELLED તરીકે રહેશે. આ પાછું નહીં થાય.',
      'wrong supplier / duplicate entry / goods returned': 'ખોટો સપ્લાયર / બેવડી એન્ટ્રી / માલ પરત',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'ટિપ: "સપ્લાયર બિલ દાખલ કરો" આખું બિલ GST સાથે નોંધે છે અને બધી આઇટમોનો સ્ટોક એકસાથે ઉમેરે છે.',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'ગ્રાહકો જેમને વેચો છો અને સપ્લાયરો જેમની પાસેથી ખરીદો છો — GSTIN, સરનામું, ઉધાર દિવસ',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'હજુ કોઈ પાર્ટી નથી — તમારા ગ્રાહકો અને સપ્લાયરો અહીં ઉમેરો (એક-વારનું નામ બિલ પર પણ લખી શકાય).',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'સમયગાળાની આવક સપ્લાય — સપ્લાયર બિલ-વાર, HSN / દર-વાર ચૂકવેલો ટેક્સ (ઇનપુટ ટેક્સ ક્રેડિટ). B2B = GSTIN વાળો સપ્લાયર, URD = બિન-નોંધાયેલ. રદ એન્ટ્રીઓ દેખાય છે પણ સરવાળામાં નહીં.',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'હાઇલાઇટ કરેલી લાઇનનો અર્થ: \'સુધી\' તારીખનું અંતિમ બેલેન્સ આજના સ્ટોકથી અલગ છે — \'સુધી\' તારીખ પછીની હિલચાલ, અથવા એપની બહાર કરેલો ફેરફાર.',
      'Adjustment (approved)': 'એડજસ્ટમેન્ટ (મંજૂર)',
