      'Every stock change is recorded automatically with its document number — supplier bill, dispatch no., invoice no., batch code, adjustment code. Tap a row to open the document. "Opening stock" is the balance carried from before the ledger started.': 'દરેક સ્ટોક ફેરફાર તેના દસ્તાવેજ નંબર સાથે આપમેળે નોંધાય છે — સપ્લાયર બિલ, ડિસ્પેચ નં, ઇન્વૉઇસ નં, બેચ કોડ, એડજસ્ટમેન્ટ કોડ. દસ્તાવેજ ખોલવા લાઇન પર ટૅપ કરો. "શરૂઆતનો સ્ટોક" લેજર શરૂ થયા પહેલાંનું બેલેન્સ છે.',
      'Every stock change of every product and material, with its document number and the balance after the movement — like an SAP material document list (MB51). Tap the item to open its full ledger; tap the document number to open the bill / dispatch / batch.': 'દરેક પ્રોડક્ટ અને સામગ્રીનો દરેક સ્ટોક ફેરફાર, દસ્તાવેજ નંબર અને હિલચાલ પછીના બેલેન્સ સાથે — SAP મટીરિયલ ડૉક્યુમેન્ટ લિસ્ટ (MB51) જેવું. પૂરું લેજર ખોલવા આઇટમ પર ટૅપ કરો; બિલ / ડિસ્પેચ / બેચ ખોલવા દસ્તાવેજ નંબર પર.',
      'Export CSV': 'CSV એક્સપોર્ટ',
