      'Nothing paid yet — record cheque / NEFT / cash payments here.': 'अजून काही दिले नाही — चेक / NEFT / रोख पेमेंट येथे नोंदवा.',
      'Remarks (vehicle, GRN no, e-way bill…)': 'शेरा (वाहन, GRN क्र., ई-वे बिल…)',
