      'unit': 'युनिट',
      'Add at least one item with quantity.': 'किमान एक वस्तू प्रमाणासह जोडा.',
      'Every line needs a description.': 'प्रत्येक ओळीसाठी वर्णन आवश्यक.',
      'Pick the item from the list for every line (or choose "Other / service").': 'प्रत्येक ओळीसाठी यादीतून वस्तू निवडा (किंवा "इतर / सेवा" निवडा).',
      'Check this matches the total printed on the supplier\'s bill.': 'हे पुरवठादाराच्या बिलावरील एकूण रकमेशी जुळते का ते तपासा.',
      'Off — bill is recorded for payment only (use when the stock was already received manually).': 'बंद — बिल फक्त पेमेंटसाठी नोंदवले जाईल (स्टॉक आधीच मॅन्युअल घेतला असल्यास).',
      'line(s) will be added to stock — the ledger shows the bill number as reference.': 'ओळी स्टॉकमध्ये जोडल्या जातील — लेजरमध्ये बिल क्रमांक संदर्भ म्हणून दिसेल.',
      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'पुरवठादाराचे बिल जसे छापले आहे तसे भरा — प्रत्येक ओळ स्टॉकमध्ये जोडली जाते (कच्चा / पॅकिंग माल → स्टोअर लेजर, तयार माल → इन्व्हेंटरी) आणि बिल क्रमांक संदर्भ म्हणून नोंदतो.',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'आवक: प्रत्येक पुरवठादार बिल येथे नोंदवा — कच्चा माल, पॅकिंग माल किंवा तयार माल. स्टॉक आपोआप वाढतो आणि बिल क्रमांक वस्तूच्या इतिहासात दिसतो.',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'अजून खरेदी बिल नाही — माल पुरवठादाराच्या बिलासह आल्यावर "पुरवठादार बिल नोंदवा" दाबा.',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'अजून हालचाल नाही — बिल क्रमांकासह स्टॉक घेण्यासाठी पुरवठादार बिल नोंदवा.',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'खरेदी / डिस्पॅच / उत्पादन ओळ दाबून उघडा. "ओपनिंग / समायोजन" म्हणजे इतिहास ठेवण्यापूर्वी मॅन्युअल सेट केलेला स्टॉक.',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'या बिलाने जोडलेले प्रमाण स्टॉकमधून परत कमी होईल आणि लेजर नोंदी काढल्या जातील. नोंद रजिस्टरमध्ये CANCELLED म्हणून राहील. हे पूर्ववत होणार नाही.',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'नोंद रजिस्टरमध्ये CANCELLED म्हणून राहील. हे पूर्ववत होणार नाही.',
      'wrong supplier / duplicate entry / goods returned': 'चुकीचा पुरवठादार / दुहेरी नोंद / माल परत',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'टीप: "पुरवठादार बिल नोंदवा" संपूर्ण बिल GST सह नोंदवते आणि सर्व वस्तूंचा स्टॉक एकाच वेळी जोडते.',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'ग्राहक ज्यांना विकता आणि पुरवठादार ज्यांच्याकडून खरेदी करता — GSTIN, पत्ता, उधारी दिवस',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'अजून पार्टी नाही — आपले ग्राहक आणि पुरवठादार येथे जोडा (एकदाचे नाव बिलावरही लिहिता येते).',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'कालावधीतील आवक पुरवठा — पुरवठादार बिल-निहाय, HSN / दर-निहाय दिलेला कर (इनपुट टॅक्स क्रेडिट). B2B = GSTIN असलेला पुरवठादार, URD = नोंदणी नसलेला. रद्द नोंदी दिसतात पण बेरजेत नाहीत.',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'हायलाइट केलेली ओळ म्हणजे: \'पर्यंत\' तारखेची अंतिम शिल्लक आजच्या स्टॉकपेक्षा वेगळी आहे — \'पर्यंत\' तारखेनंतरच्या हालचाली, किंवा अॅपबाहेर केलेला बदल.',
      'Adjustment (approved)': 'समायोजन (मंजूर)',
      'Adjustment no': 'समायोजन क्र.',
      'All items': 'सर्व आयटम',
