      'Dispatch voided (returned)': 'डिस्पॅच रद्द (परत)',
      'Doc / Bill no': 'डॉक / बिल क्र.',
      'Documents': 'दस्तऐवज',
      'Every stock change is recorded automatically with its document number — supplier bill, dispatch no., invoice no., batch code, adjustment code. Tap a row to open the document. "Opening stock" is the balance carried from before the ledger started.': 'प्रत्येक स्टॉक बदल त्याच्या दस्तऐवज क्रमांकासह आपोआप नोंदवला जातो — पुरवठादार बिल, डिस्पॅच क्र., इनव्हॉइस क्र., बॅच कोड, समायोजन कोड. दस्तऐवज उघडण्यासाठी ओळीवर टॅप करा. "सुरुवातीचा स्टॉक" म्हणजे लेजर सुरू होण्यापूर्वीची शिल्लक.',
