      'line(s) will be added to stock — the ledger shows the bill number as reference.': 'লাইন স্টকে যোগ হবে — লেজারে বিল নম্বর রেফারেন্স হিসেবে দেখাবে।',
      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'সরবরাহকারীর বিল যেমন ছাপা আছে তেমন লিখুন — প্রতিটি লাইন স্টকে যোগ হয় (কাঁচামাল / প্যাকিং → স্টোর লেজার, তৈরি পণ্য → ইনভেন্টরি) এবং বিল নম্বর রেফারেন্স হিসেবে থাকে।',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'আগমন: প্রতিটি সরবরাহকারীর বিল এখানে লিখুন — কাঁচামাল, প্যাকিং বা তৈরি পণ্য। স্টক নিজে থেকে বাড়ে এবং বিল নম্বর আইটেমের ইতিহাসে দেখায়।',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'এখনও কোনো ক্রয় বিল নেই — সরবরাহকারীর বিলসহ মাল এলে "সরবরাহকারীর বিল লিখুন" চাপুন।',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'এখনও কোনো লেনদেন নেই — বিল নম্বরসহ স্টক নিতে সরবরাহকারীর বিল লিখুন।',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'ক্রয় / ডিসপ্যাচ / উৎপাদন সারিতে চাপ দিয়ে খুলুন। "ওপেনিং / সমন্বয়" হলো ইতিহাস রাখার আগে ম্যানুয়ালি সেট করা স্টক।',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'এই বিলে যোগ করা পরিমাণ স্টক থেকে ফেরত কমানো হবে এবং লেজার এন্ট্রি মুছে যাবে। এন্ট্রি রেজিস্টারে CANCELLED হিসেবে থাকবে। এটি ফেরানো যাবে না।',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'এন্ট্রি রেজিস্টারে CANCELLED হিসেবে থাকবে। এটি ফেরানো যাবে না।',
      'wrong supplier / duplicate entry / goods returned': 'ভুল সরবরাহকারী / দ্বৈত এন্ট্রি / মাল ফেরত',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'টিপ: "সরবরাহকারীর বিল লিখুন" GST-সহ পুরো বিল লেখে এবং সব আইটেমের স্টক একসাথে যোগ করে।',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'যাদের বিক্রি করেন সেই গ্রাহক ও যাদের থেকে কেনেন সেই সরবরাহকারী — GSTIN, ঠিকানা, বাকির দিন',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'এখনও কোনো পার্টি নেই — আপনার গ্রাহক ও সরবরাহকারী এখানে যোগ করুন (এককালীন নাম বিলেও লেখা যায়)।',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'সময়কালের আগমন সরবরাহ — সরবরাহকারীর বিল-ভিত্তিক, HSN / হার-ভিত্তিক প্রদত্ত কর (ইনপুট ট্যাক্স ক্রেডিট)। B2B = GSTIN-সহ সরবরাহকারী, URD = অনিবন্ধিত। বাতিল এন্ট্রি দেখানো হয় কিন্তু যোগে নেই।',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'হাইলাইট করা সারির মানে: \'পর্যন্ত\' তারিখের সমাপনী ব্যালেন্স আজকের স্টক থেকে আলাদা — \'পর্যন্ত\' তারিখের পরের মুভমেন্ট, বা অ্যাপের বাইরে করা পরিবর্তন।',
      'Adjustment (approved)': 'সমন্বয় (অনুমোদিত)',
      'Adjustment no': 'সমন্বয় নং',
