      'All types': 'সব ধরন',
      'Balance synced': 'ব্যালেন্স সিঙ্ক করা হয়েছে',
      'Bill / dispatch / invoice no, party, note…': 'বিল / ডিসপ্যাচ / ইনভয়েস নং, পার্টি, নোট…',
      'Changed outside the app': 'অ্যাপের বাইরে পরিবর্তিত',
      'Clear dates': 'তারিখ মুছুন',
