      'Doc / Bill no': 'ডক / বিল নং',
      'Documents': 'নথি',
      'Every stock change is recorded automatically with its document number — supplier bill, dispatch no., invoice no., batch code, adjustment code. Tap a row to open the document. "Opening stock" is the balance carried from before the ledger started.': 'প্রতিটি স্টক পরিবর্তন তার নথি নম্বরসহ স্বয়ংক্রিয়ভাবে রেকর্ড হয় — সরবরাহকারী বিল, ডিসপ্যাচ নং, ইনভয়েস নং, ব্যাচ কোড, সমন্বয় কোড। নথি খুলতে সারিতে ট্যাপ করুন। "প্রারম্ভিক স্টক" হল লেজার শুরুর আগের ব্যালেন্স।',
      'Every stock change of every product and material, with its document number and the balance after the movement — like an SAP material document list (MB51). Tap the item to open its full ledger; tap the document number to open the bill / dispatch / batch.': 'প্রতিটি পণ্য ও উপকরণের প্রতিটি স্টক পরিবর্তন, নথি নম্বর ও মুভমেন্টের পরের ব্যালেন্সসহ — SAP ম্যাটেরিয়াল ডকুমেন্ট লিস্ট (MB51)-এর মতো। পুরো লেজার খুলতে আইটেমে ট্যাপ করুন; বিল / ডিসপ্যাচ / ব্যাচ খুলতে নথি নম্বরে।',
      'Export CSV': 'CSV এক্সপোর্ট',
      'Exported (CSV) — open in Excel or share.': 'এক্সপোর্ট হয়েছে (CSV) — Excel-এ খুলুন বা শেয়ার করুন।',
      'Find a bill / dispatch / invoice / batch no': 'বিল / ডিসপ্যাচ / ইনভয়েস / ব্যাচ নং খুঁজুন',
