      'Goods received against a supplier invoice? Use Billing → Purchases (Inward) instead — it records the bill number, GST and payable too.': 'সরবরাহকারীর ইনভয়েসের বিপরীতে মাল এসেছে? এর বদলে বিলিং → ক্রয় (ইনওয়ার্ড) ব্যবহার করুন — এটি বিল নম্বর, GST ও দেনাও রেকর্ড করে।',
