      'No stock movements in this period.': 'এই মেয়াদে কোনো স্টক মুভমেন্ট নেই।',
      'One line per document number in the period — supplier bills, dispatches, invoices, production batches, adjustments — with the number of item lines and the quantity moved. Tap to open the document.': 'মেয়াদের প্রতিটি নথি নম্বরের একটি সারি — সরবরাহকারী বিল, ডিসপ্যাচ, ইনভয়েস, উৎপাদন ব্যাচ, সমন্বয় — আইটেম সারির সংখ্যা ও সরানো পরিমাণসহ। নথি খুলতে ট্যাপ করুন।',
      'Opening (period)': 'প্রারম্ভিক (মেয়াদ)',
      'Opening balance, total in, total out and closing balance of every item for the period, next to the live stock (MB5B). Opening = balance before the From date. Tap an item for its full ledger.': 'মেয়াদের জন্য প্রতিটি আইটেমের প্রারম্ভিক ব্যালেন্স, মোট ইন, মোট আউট ও সমাপনী ব্যালেন্স, লাইভ স্টকের পাশে (MB5B)। প্রারম্ভিক = \'থেকে\' তারিখের আগের ব্যালেন্স। পুরো লেজারের জন্য আইটেমে ট্যাপ করুন।',
