      'For product (optional)': 'কোন প্রোডাক্টের জন্য (ঐচ্ছিক)',
      'Tags the consumption to a product in the stock ledger': 'স্টক লেজারে খরচকে এই প্রোডাক্টের সাথে যুক্ত করে',
      'Stock differs from the ledger balance by': 'স্টক লেজার ব্যালেন্স থেকে এতটা আলাদা:',
      'Stock ledger': 'স্টক লেজার',
      'Stock ledger (all in / out with doc numbers)': 'স্টক লেজার (সব ইন / আউট নথি নম্বরসহ)',
