      'Stock set (physical count)': 'স্টক সেট (বাস্তব গণনা)',
      'The difference is posted to the stock ledger as "Stock set (physical count)" with this reference.': 'পার্থক্যটি স্টক লেজারে "স্টক সেট (বাস্তব গণনা)" হিসেবে এই রেফারেন্সসহ পোস্ট হয়।',
      'The stock ledger is not enabled on this server yet. Ask your admin to run the stock-ledger update (tools/ff-stockledger.sh) — after that every stock movement is recorded here automatically.': 'এই সার্ভারে স্টক লেজার এখনও চালু হয়নি। আপনার অ্যাডমিনকে স্টক-লেজার আপডেট (tools/ff-stockledger.sh) চালাতে বলুন — তারপর প্রতিটি স্টক মুভমেন্ট এখানে স্বয়ংক্রিয়ভাবে রেকর্ড হবে।',
      'This financial year': 'এই অর্থবছর',
      'This month': 'এই মাস',
      'This server has not been updated with the stock ledger yet — showing the derived purchase / production / dispatch / sale history. Ask your admin to run the stock-ledger update.': 'এই সার্ভার এখনও স্টক লেজার দিয়ে আপডেট হয়নি — ক্রয় / উৎপাদন / ডিসপ্যাচ / বিক্রয় থেকে তৈরি ইতিহাস দেখানো হচ্ছে। অ্যাডমিনকে স্টক-লেজার আপডেট চালাতে বলুন।',
      'Today': 'আজ',
