      'Top items bought this month': 'இந்த மாதம் அதிகம் வாங்கிய பொருட்கள்',
      'Rate-wise tax paid (ITC)': 'விகித வாரியாக செலுத்திய வரி (ITC)',
      'Bill-wise purchase register': 'பில் வாரியாக கொள்முதல் பதிவேடு',
      'Export CSV (purchase register)': 'CSV ஏற்றுமதி (கொள்முதல் பதிவேடு)',
      'No purchase bills in this period': 'இந்த காலத்தில் கொள்முதல் பில்கள் இல்லை',
      'Nothing to pay — all supplier bills are settled 🎉': 'செலுத்த எதுவும் இல்லை — அனைத்து சப்ளையர் பில்களும் தீர்க்கப்பட்டன 🎉',
      'No payments.': 'பணம் செலுத்தப்படவில்லை.',
      'Nothing paid yet — record cheque / NEFT / cash payments here.': 'இன்னும் செலுத்தவில்லை — காசோலை / NEFT / ரொக்கம் இங்கே பதிவு செய்யவும்.',
      'Remarks (vehicle, GRN no, e-way bill…)': 'குறிப்புகள் (வாகனம், GRN எண், e-way bill…)',
      'Freight / loading / service': 'சரக்கு கட்டணம் / ஏற்றுதல் / சேவை',
      'unit': 'அலகு',
      'Add at least one item with quantity.': 'அளவுடன் குறைந்தது ஒரு பொருளைச் சேர்க்கவும்.',
      'Every line needs a description.': 'ஒவ்வொரு வரிக்கும் விவரம் தேவை.',
      'Pick the item from the list for every line (or choose "Other / service").': 'ஒவ்வொரு வரிக்கும் பட்டியலிலிருந்து பொருளைத் தேர்வு செய்யவும் (அல்லது "மற்றவை / சேவை").',
      'Check this matches the total printed on the supplier\'s bill.': 'சப்ளையர் பில்லில் அச்சிடப்பட்ட மொத்தத்துடன் இது பொருந்துகிறதா என சரிபார்க்கவும்.',
      'Off — bill is recorded for payment only (use when the stock was already received manually).': 'அணைப்பு — பில் பணம் செலுத்த மட்டுமே பதிவாகும் (இருப்பு ஏற்கனவே கைமுறையாகப் பெறப்பட்டிருந்தால்).',
      'line(s) will be added to stock — the ledger shows the bill number as reference.': 'வரிகள் இருப்பில் சேர்க்கப்படும் — லெட்ஜரில் பில் எண் குறிப்பாகக் காட்டப்படும்.',
      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'சப்ளையர் பில்லை அச்சிட்டபடியே உள்ளிடவும் — ஒவ்வொரு வரியும் இருப்பில் சேரும் (மூலப்பொருள் / பேக்கிங் → ஸ்டோர் லெட்ஜர், முடிக்கப்பட்ட பொருட்கள் → இன்வென்டரி), பில் எண் குறிப்பாகப் பதிவாகும்.',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'உள்வரவு: ஒவ்வொரு சப்ளையர் பில்லையும் இங்கே பதிவு செய்யவும் — மூலப்பொருள், பேக்கிங் அல்லது முடிக்கப்பட்ட பொருட்கள். இருப்பு தானாக உயரும், பில் எண் பொருளின் வரலாற்றில் காட்டப்படும்.',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'இன்னும் கொள்முதல் பில்கள் இல்லை — சப்ளையர் பில்லுடன் பொருள் வரும்போது "சப்ளையர் பில் பதிவு" அழுத்தவும்.',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'இன்னும் நகர்வுகள் இல்லை — பில் எண்ணுடன் இருப்பைப் பெற சப்ளையர் பில் பதிவு செய்யவும்.',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'கொள்முதல் / அனுப்புகை / உற்பத்தி வரியைத் தட்டித் திறக்கவும். "தொடக்கம் / சரிசெய்தல்" என்பது வரலாறு பதிவுக்கு முன் கைமுறையாக அமைக்கப்பட்ட இருப்பு.',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'இந்த பில்லால் சேர்க்கப்பட்ட அளவுகள் இருப்பிலிருந்து திரும்பக் குறைக்கப்படும், லெட்ஜர் பதிவுகள் நீக்கப்படும். பதிவு CANCELLED எனப் பதிவேட்டில் இருக்கும். இதை மாற்ற முடியாது.',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'பதிவு CANCELLED எனப் பதிவேட்டில் இருக்கும். இதை மாற்ற முடியாது.',
      'wrong supplier / duplicate entry / goods returned': 'தவறான சப்ளையர் / இரட்டைப் பதிவு / பொருள் திரும்பியது',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'குறிப்பு: "சப்ளையர் பில் பதிவு" GST உடன் முழு பில்லையும் பதிவு செய்து அனைத்துப் பொருட்களின் இருப்பையும் ஒரே நேரத்தில் சேர்க்கும்.',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'நீங்கள் விற்கும் வாடிக்கையாளர்கள் மற்றும் வாங்கும் சப்ளையர்கள் — GSTIN, முகவரி, கடன் நாட்கள்',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'இன்னும் பார்ட்டிகள் இல்லை — உங்கள் வாடிக்கையாளர்கள் மற்றும் சப்ளையர்களை இங்கே சேர்க்கவும் (ஒருமுறை பெயரை பில்லிலும் எழுதலாம்).',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'காலத்தின் உள்வரவு விநியோகங்கள் — சப்ளையர் பில் வாரியாக, HSN / விகித வாரியாக செலுத்திய வரி (உள்ளீட்டு வரி வரவு). B2B = GSTIN உள்ள சப்ளையர், URD = பதிவு செய்யப்படாதவர். ரத்தான பதிவுகள் காட்டப்படும் ஆனால் கூட்டப்படாது.',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'ஹைலைட் செய்யப்பட்ட வரிசை: \'வரை\' தேதியின் இறுதி இருப்பு இன்றைய கையிருப்பிலிருந்து வேறுபடுகிறது — \'வரை\' தேதிக்குப் பிந்தைய நகர்வுகள், அல்லது ஆப்பிற்கு வெளியே செய்த மாற்றம்.',
      'Adjustment (approved)': 'சரிசெய்தல் (அங்கீகரிக்கப்பட்டது)',
      'Adjustment no': 'சரிசெய்தல் எண்',
      'All items': 'எல்லா பொருட்களும்',
      'All types': 'எல்லா வகைகளும்',
      'Balance synced': 'இருப்பு ஒத்திசைக்கப்பட்டது',
      'Bill / dispatch / invoice no, party, note…': 'பில் / அனுப்புகை / விலைப்பட்டியல் எண், தரப்பு, குறிப்பு…',
      'Changed outside the app': 'ஆப்பிற்கு வெளியே மாற்றப்பட்டது',
      'Clear dates': 'தேதிகளை அழி',
      'Closing (period)': 'இறுதி (காலம்)',
      'Dispatch no': 'அனுப்புகை எண்',
      'Dispatch voided (returned)': 'அனுப்புகை ரத்து (திரும்பியது)',
      'Doc / Bill no': 'ஆவணம் / பில் எண்',
      'Documents': 'ஆவணங்கள்',
      'Every stock change is recorded automatically with its document number — supplier bill, dispatch no., invoice no., batch code, adjustment code. Tap a row to open the document. "Opening stock" is the balance carried from before the ledger started.': 'ஒவ்வொரு கையிருப்பு மாற்றமும் அதன் ஆவண எண்ணுடன் தானாகப் பதிவாகிறது — சப்ளையர் பில், அனுப்புகை எண், விலைப்பட்டியல் எண், தொகுதிக் குறியீடு, சரிசெய்தல் குறியீடு. ஆவணத்தைத் திறக்க வரிசையைத் தட்டவும். "தொடக்க இருப்பு" என்பது லெட்ஜர் தொடங்கும் முன் இருந்த இருப்பு.',
      'Every stock change of every product and material, with its document number and the balance after the movement — like an SAP material document list (MB51). Tap the item to open its full ledger; tap the document number to open the bill / dispatch / batch.': 'ஒவ்வொரு தயாரிப்பு மற்றும் பொருளின் ஒவ்வொரு கையிருப்பு மாற்றமும், ஆவண எண் மற்றும் நகர்வுக்குப் பிந்தைய இருப்புடன் — SAP மெட்டீரியல் டாக்குமெண்ட் பட்டியல் (MB51) போல. முழு லெட்ஜரைத் திறக்க பொருளைத் தட்டவும்; பில் / அனுப்புகை / தொகுதியைத் திறக்க ஆவண எண்ணைத் தட்டவும்.',
      'Export CSV': 'CSV ஏற்றுமதி',
      'Exported (CSV) — open in Excel or share.': 'ஏற்றுமதி ஆனது (CSV) — Excel-இல் திறக்கவும் அல்லது பகிரவும்.',
      'Find a bill / dispatch / invoice / batch no': 'பில் / அனுப்புகை / விலைப்பட்டியல் / தொகுதி எண்ணைத் தேடு',
      'Finished products': 'முடிக்கப்பட்ட தயாரிப்புகள்',
      'From (party / depot)': 'எங்கிருந்து (தரப்பு / டிப்போ)',
      'GRN / challan / ref no': 'GRN / சலான் / குறிப்பு எண்',
      'Goods received against a supplier invoice? Use Billing → Purchases (Inward) instead — it records the bill number, GST and payable too.': 'சப்ளையர் விலைப்பட்டியலுக்கு எதிராகப் பொருள் வந்ததா? அதற்குப் பதிலாக பில்லிங் → கொள்முதல் (உள்வரவு) பயன்படுத்தவும் — அது பில் எண், GST மற்றும் செலுத்த வேண்டியதையும் பதிவு செய்கிறது.',
      'In': 'உள்',
      'In (period)': 'உள் (காலம்)',
      'Invoice cancelled (restored)': 'விலைப்பட்டியல் ரத்து (இருப்பு மீட்பு)',
      'Invoice no': 'விலைப்பட்டியல் எண்',
      'Issue / consumed': 'வழங்கல் / பயன்பாடு',
      'Item deleted': 'பொருள் நீக்கப்பட்டது',
      'Item lines': 'பொருள் வரிசைகள்',
      'Item name / code': 'பொருள் பெயர் / குறியீடு',
      'Last 7 days': 'கடந்த 7 நாட்கள்',
      'Last month': 'கடந்த மாதம்',
      'Last movement': 'கடைசி நகர்வு',
      'Ledger exported (CSV) — open in Excel or share.': 'லெட்ஜர் ஏற்றுமதி ஆனது (CSV) — Excel-இல் திறக்கவும் அல்லது பகிரவும்.',
      'Materials': 'பொருட்கள்',
      'Moved in period only': 'காலத்தில் நகர்ந்தவை மட்டும்',
      'Movement': 'நகர்வு',
      'Movement register': 'நகர்வுப் பதிவேடு',
      'Movement types': 'நகர்வு வகைகள்',
      'Movements': 'நகர்வுகள்',
      'No documents in this period.': 'இந்தக் காலத்தில் ஆவணங்கள் இல்லை.',
      'No items match.': 'பொருந்தும் பொருள் இல்லை.',
      'No stock movements in this period.': 'இந்தக் காலத்தில் கையிருப்பு நகர்வுகள் இல்லை.',
      'One line per document number in the period — supplier bills, dispatches, invoices, production batches, adjustments — with the number of item lines and the quantity moved. Tap to open the document.': 'காலத்தில் ஒவ்வொரு ஆவண எண்ணுக்கும் ஒரு வரிசை — சப்ளையர் பில்கள், அனுப்புகைகள், விலைப்பட்டியல்கள், உற்பத்தித் தொகுதிகள், சரிசெய்தல்கள் — பொருள் வரிசைகளின் எண்ணிக்கை மற்றும் நகர்த்திய அளவுடன். ஆவணத்தைத் திறக்கத் தட்டவும்.',
      'Opening (period)': 'தொடக்க (காலம்)',
      'Opening balance, total in, total out and closing balance of every item for the period, next to the live stock (MB5B). Opening = balance before the From date. Tap an item for its full ledger.': 'காலத்திற்கான ஒவ்வொரு பொருளின் தொடக்க இருப்பு, மொத்த உள், மொத்த வெளி மற்றும் இறுதி இருப்பு, நேரடி கையிருப்புடன் (MB5B). தொடக்கம் = \'முதல்\' தேதிக்கு முந்தைய இருப்பு. முழு லெட்ஜருக்கு பொருளைத் தட்டவும்.',
      'Out': 'வெளி',
      'Out (period)': 'வெளி (காலம்)',
      'Period Balances': 'கால இருப்புகள்',
      'Preparing…': 'தயாராகிறது…',
      'Products': 'தயாரிப்புகள்',
      'Purchase cancelled (reversed)': 'கொள்முதல் ரத்து (திருப்பப்பட்டது)',
      'Qty in': 'அளவு உள்',
      'Qty out': 'அளவு வெளி',
      'Quick period': 'விரைவு காலம்',
      'Raw & packing materials': 'மூலப்பொருள் & பேக்கிங் பொருட்கள்',
      'Receipt (GRN)': 'பெறுகை (GRN)',
      'Recipe': 'செய்முறை',
      'Recipe consumption': 'செய்முறை பயன்பாடு',
      'Recorded': 'பதிவு',
      'Reference': 'குறிப்பு',
      'Reference / count sheet no (optional)': 'குறிப்பு / எண்ணிக்கைத் தாள் எண் (விருப்பம்)',
      'Reversal': 'திருப்பம்',
      'Stock Ledger': 'கையிருப்பு லெட்ஜர்',
      'For product (optional)': 'எந்த தயாரிப்புக்கு (விருப்பம்)',
      'Tags the consumption to a product in the stock ledger': 'கையிருப்பு லெட்ஜரில் நுகர்வை இந்த தயாரிப்புடன் இணைக்கிறது',
      'Stock differs from the ledger balance by': 'கையிருப்பு லெட்ஜர் இருப்பிலிருந்து இவ்வளவு வேறுபடுகிறது:',
      'Stock ledger': 'கையிருப்பு லெட்ஜர்',
      'Stock ledger (all in / out with doc numbers)': 'கையிருப்பு லெட்ஜர் (அனைத்து உள் / வெளி ஆவண எண்களுடன்)',
      'Stock now': 'தற்போதைய இருப்பு',
      'Stock set (physical count)': 'இருப்பு அமைப்பு (நேரடி எண்ணிக்கை)',
      'The difference is posted to the stock ledger as "Stock set (physical count)" with this reference.': 'வேறுபாடு கையிருப்பு லெட்ஜரில் "இருப்பு அமைப்பு (நேரடி எண்ணிக்கை)" எனக் இந்தக் குறிப்புடன் பதிவாகிறது.',
      'The stock ledger is not enabled on this server yet. Ask your admin to run the stock-ledger update (tools/ff-stockledger.sh) — after that every stock movement is recorded here automatically.': 'இந்த சேவையகத்தில் கையிருப்பு லெட்ஜர் இன்னும் இயக்கப்படவில்லை. உங்கள் நிர்வாகியிடம் கையிருப்பு-லெட்ஜர் புதுப்பிப்பை (tools/ff-stockledger.sh) இயக்கச் சொல்லுங்கள் — அதன் பிறகு ஒவ்வொரு கையிருப்பு நகர்வும் இங்கே தானாகப் பதிவாகும்.',
      'This financial year': 'இந்த நிதியாண்டு',
      'This month': 'இந்த மாதம்',
      'This server has not been updated with the stock ledger yet — showing the derived purchase / production / dispatch / sale history. Ask your admin to run the stock-ledger update.': 'இந்த சேவையகம் இன்னும் கையிருப்பு லெட்ஜருடன் புதுப்பிக்கப்படவில்லை — கொள்முதல் / உற்பத்தி / அனுப்புகை / விற்பனையிலிருந்து பெறப்பட்ட வரலாறு காட்டப்படுகிறது. நிர்வாகியிடம் கையிருப்பு-லெட்ஜர் புதுப்பிப்பை இயக்கச் சொல்லுங்கள்.',
      'Today': 'இன்று',
      'a SYNC line will be posted at the next server restart.': 'அடுத்த சேவையக மறுதொடக்கத்தில் ஒரு SYNC வரிசை பதிவாகும்.',
      'all units summed': 'எல்லா அலகுகளும் கூட்டி',
      'materials': 'பொருட்கள்',
      'optional': 'விருப்பம்',
      'products': 'தயாரிப்புகள்',
      'tap to open': 'திறக்கத் தட்டவும்',
