      'Amounts are as per recipe — type in any box to give that material a specific consumption instead. 0 = skip.': 'పరిమాణాలు రెసిపీ ప్రకారం — ఏ బాక్స్‌లోనైనా రాసి ప్రత్యేక వినియోగం ఇవ్వండి. 0 = దాటవేయి.',
