      'No purchase bills in this period': 'ఈ కాలంలో కొనుగోలు బిల్లులు లేవు',
      'Nothing to pay — all supplier bills are settled 🎉': 'చెల్లించవలసినది ఏమీ లేదు — అన్ని సప్లయర్ బిల్లులు తీరాయి 🎉',
      'No payments.': 'చెల్లింపులు లేవు.',
      'Nothing paid yet — record cheque / NEFT / cash payments here.': 'ఇంకా ఏమీ చెల్లించలేదు — చెక్ / NEFT / నగదు చెల్లింపులు ఇక్కడ నమోదు చేయండి.',
      'Remarks (vehicle, GRN no, e-way bill…)': 'రిమార్క్స్ (వాహనం, GRN నం, ఇ-వే బిల్లు…)',
      'Freight / loading / service': 'రవాణా / లోడింగ్ / సేవ',
      'unit': 'యూనిట్',
      'Add at least one item with quantity.': 'పరిమాణంతో కనీసం ఒక వస్తువు జోడించండి.',
      'Every line needs a description.': 'ప్రతి లైన్‌కు వివరణ అవసరం.',
      'Pick the item from the list for every line (or choose "Other / service").': 'ప్రతి లైన్‌కు జాబితా నుండి వస్తువు ఎంచుకోండి (లేదా "ఇతర / సేవ").',
      'Check this matches the total printed on the supplier\'s bill.': 'ఇది సప్లయర్ బిల్లుపై ముద్రించిన మొత్తంతో సరిపోతుందో చూడండి.',
      'Off — bill is recorded for payment only (use when the stock was already received manually).': 'ఆఫ్ — బిల్లు చెల్లింపు కోసం మాత్రమే నమోదవుతుంది (స్టాక్ ఇప్పటికే మాన్యువల్‌గా అందితే).',
      'line(s) will be added to stock — the ledger shows the bill number as reference.': 'లైన్లు స్టాక్‌కు జోడించబడతాయి — లెడ్జర్‌లో బిల్లు నంబర్ రిఫరెన్స్‌గా కనిపిస్తుంది.',
      'Enter the supplier\'s bill exactly as printed — every line adds to stock (raw / packing material → store ledger, finished goods → inventory) with the bill number as reference.': 'సప్లయర్ బిల్లును ముద్రించినట్లే నమోదు చేయండి — ప్రతి లైన్ స్టాక్‌కు జోడించబడుతుంది (ముడి / ప్యాకింగ్ → స్టోర్ లెడ్జర్, తయారైన సరుకు → ఇన్వెంటరీ), బిల్లు నంబర్ రిఫరెన్స్‌గా ఉంటుంది.',
      'Inward: enter every supplier bill here — raw material, packing material or finished goods. Stock goes up automatically and the bill number shows in the item history.': 'ఇన్‌వర్డ్: ప్రతి సప్లయర్ బిల్లు ఇక్కడ నమోదు చేయండి — ముడి, ప్యాకింగ్ లేదా తయారైన సరుకు. స్టాక్ ఆటోమేటిక్‌గా పెరుగుతుంది, బిల్లు నంబర్ వస్తువు చరిత్రలో కనిపిస్తుంది.',
      'No purchase bills yet — tap "Enter Supplier Bill" when goods arrive with the supplier\'s invoice.': 'ఇంకా కొనుగోలు బిల్లులు లేవు — సరుకు సప్లయర్ బిల్లుతో వచ్చినప్పుడు "సప్లయర్ బిల్లు నమోదు" నొక్కండి.',
      'No movements yet — enter a supplier bill to receive stock against an invoice number.': 'ఇంకా కదలికలు లేవు — బిల్లు నంబర్‌తో స్టాక్ అందుకోవడానికి సప్లయర్ బిల్లు నమోదు చేయండి.',
      'Tap a purchase / dispatch / production row to open it. "Opening / adjustment" is the balancing figure for stock set manually before history was kept.': 'కొనుగోలు / డిస్పాచ్ / ఉత్పత్తి వరుసను నొక్కి తెరవండి. "ఓపెనింగ్ / సర్దుబాటు" అనేది చరిత్రకు ముందు మాన్యువల్‌గా సెట్ చేసిన స్టాక్.',
      'The quantities added by this bill are taken back out of stock and the ledger entries are removed. The entry stays in the register marked CANCELLED. This cannot be undone.': 'ఈ బిల్లుతో జోడించిన పరిమాణాలు స్టాక్ నుండి వెనక్కి తీసివేయబడతాయి, లెడ్జర్ ఎంట్రీలు తొలగించబడతాయి. ఎంట్రీ రిజిస్టర్‌లో CANCELLED గా ఉంటుంది. దీన్ని రద్దు చేయలేరు.',
      'The entry stays in the register marked CANCELLED. This cannot be undone.': 'ఎంట్రీ రిజిస్టర్‌లో CANCELLED గా ఉంటుంది. దీన్ని రద్దు చేయలేరు.',
      'wrong supplier / duplicate entry / goods returned': 'తప్పు సప్లయర్ / డూప్లికేట్ ఎంట్రీ / సరుకు తిరిగి',
      'Tip: "Enter Supplier Bill" records the full bill with GST and adds stock for all items at once.': 'చిట్కా: "సప్లయర్ బిల్లు నమోదు" GSTతో పూర్తి బిల్లును నమోదు చేసి అన్ని వస్తువుల స్టాక్‌ను ఒకేసారి జోడిస్తుంది.',
      'customers you sell to and suppliers you buy from — GSTIN, address, credit days': 'మీరు అమ్మే కస్టమర్లు మరియు కొనే సప్లయర్లు — GSTIN, చిరునామా, క్రెడిట్ రోజులు',
      'No parties yet — add your customers and suppliers here (a one-time name can also be typed on the invoice / bill).': 'ఇంకా పార్టీలు లేవు — మీ కస్టమర్లు మరియు సప్లయర్లను ఇక్కడ జోడించండి (ఒకసారి పేరు బిల్లుపై కూడా టైప్ చేయవచ్చు).',
      'Inward supplies for the period — supplier bill-wise, HSN / rate-wise tax paid (input tax credit). B2B = supplier with GSTIN, URD = unregistered. Cancelled entries are listed but not totalled.': 'కాలానికి ఇన్‌వర్డ్ సరఫరాలు — సప్లయర్ బిల్లు వారీగా, HSN / రేటు వారీగా చెల్లించిన పన్ను (ఇన్‌పుట్ టాక్స్ క్రెడిట్). B2B = GSTIN ఉన్న సప్లయర్, URD = నమోదు కాని. రద్దైన ఎంట్రీలు చూపబడతాయి కానీ మొత్తంలో కలవవు.',
      // ---- stock ledger (SAP-style movement register) ----
      'A highlighted row means the closing balance on the To date differs from today\'s stock — movements after the To date, or a change made outside the app.': 'హైలైట్ చేసిన వరుస అర్థం: \'వరకు\' తేదీ ముగింపు నిల్వ నేటి స్టాక్‌తో భిన్నంగా ఉంది — \'వరకు\' తేదీ తర్వాతి కదలికలు, లేదా యాప్ బయట చేసిన మార్పు.',
      'Adjustment (approved)': 'సర్దుబాటు (ఆమోదించబడింది)',
